function showResult(){battle.effects=[];if(battle.preview){$('#battle-controls').classList.add('hidden');const el=$('#result');el.classList.remove('hidden');el.classList.add('result');el.innerHTML=`<h2>${q('Démonstration terminée','Showcase complete')}</h2><p>${q('Aucune énergie dépensée. Aucun cœur perdu.','No energy spent. No hearts lost.')}</p><div class="row gap">${btn(q('Revoir','Replay'),'replay','','grow')}${btn(q('Retour aux héros','Back to heroes'),'nav','data-page="home"','primary grow')}</div>`;return;}let r=battle.result;$('#battle-controls').classList.add('hidden');let el=$('#result');el.classList.remove('hidden');el.classList.add('result');el.innerHTML=`<h2>${r.winner===0?q('Victoire !','Victory!'):r.winner===1?q('Défaite','Defeat'):q('Match nul','Draw')}</h2><p>+${battle.amount.toFixed(2)} XP · −20 ⚡</p>${battle.points?`<p class="gold gap">◆ +${battle.points} ${q('points de compagnie','company points')}</p>`:''}${battle.loot?`<div class="loot rarity-${rarity(battle.loot)} gap"><b>${q('Butin obtenu','Loot found')}</b><h3>${esc(itemName(battle.loot))}</h3><p>${esc(itemText(battle.loot))}</p><small>${q('Ajouté à son inventaire. À équiper avant le prochain combat.','Added to this hero’s inventory. Equip before the next battle.')}</small></div>`:battle.hearts>0?`<p class="gap">${q('Aucun butin cette fois.','No loot this time.')}</p>`:''}<div class="gap">${hearts({hearts:battle.hearts})}</div><p>${battle.hearts===0?q('Ton héros est tombé pour la dernière fois.','Your hero has fallen for the last time.'):r.winner===1?q('Un cœur perdu. La progression continue.','One heart lost. The journey continues.'):q('Tes cœurs sont conservés.','Your hearts are preserved.')}</p><div class="row gap">${btn(q('Revoir','Replay'),'replay','','grow')}${btn(battle.hearts===0?q('Voir sa carrière','View career'):q('Continuer','Continue'),'battle-done','','primary grow')}</div>`;}
const actions={'mage-demo':()=>startArtDemo('mage'),'art-demo':()=>startArtDemo(),nav:el=>{let p=el.dataset.page;go(p);},select:el=>{game.selected=el.dataset.id;save();go('detail');},detail:()=>go('detail'),recruit:()=>{if(game.heroes.length>=5)return;candidate=hero();go('recruit');},reroll:()=>{candidate=hero();render();},confirm:()=>{if(!candidate||game.heroes.length>=5)return;candidate.name=$('#hero-name').value.trim().slice(0,28)||candidate.name;ensureArena(candidate);game.heroes.push(candidate);game.selected=candidate.id;candidate=null;save();go('detail');},arena:()=>go('opponents'),refresh:()=>{let h=selected();if(!h)return;const old=structuredClone(h.arena);if(rerollArena(h)){if(!save())h.arena=old;render();}},fight:el=>startFight(+el.dataset.index),rewards:()=>go('rewards'),reward:el=>{let h=selected(),p=h?.pending[0],i=+el.dataset.index;if(!p)return;if(p.type==='stat'){if(i<0||i>4)return;h.stats[i]++;}else if(i>=0){if(!p.offers[i])return;acquireItem(h,p.offers[i]);}h.pending.shift();save();go(h.pending.length?'rewards':'detail');},memorial:el=>{memorialId=el.dataset.id;go('memorial');},'close-memorial':()=>{game.deathNotice=null;save();go('graveyard');},speed:el=>{battle.speed=battle.speed===1?2:1;el.textContent=battle.speed+'×';},skip:()=>{battle.time=battle.result.duration;},replay:()=>playLast(battle.preview?battle:game.lastBattle),'battle-done':()=>{if(battle.hearts===0){memorialId=battle.heroId;go('memorial');}else{game.selected=battle.heroId;save();go(selected()?.pending.length?'rewards':'detail');}},'dev-energy':()=>{game.heroes.forEach(h=>{h.energy=100;h.energy_time=Date.now()/1000;});save();toast(q('Énergie rechargée','Energy refilled'));},'dev-xp':()=>{let h=selected();if(!h){toast(q('Crée un héros d’abord','Recruit a hero first'));return;}grantXP(h,10);save();toast('+10 XP');},'dev-items':()=>{let h=selected();if(!h)return;D.ITEMS.forEach((_,id)=>{if(!h.inventory.some(it=>it.id===id&&it.level===h.level))acquireItem(h,{id,level:h.level});});save();toast(q('Équipements ajoutés','Equipment added'));},'dev-class':()=>{if(game.heroes.length>=5){toast(q('Les cinq places sont occupées','All five slots are occupied'));return;}candidate=hero(1,+$('#dev-class').value);go('recruit');},export:()=>{game.heroes.forEach(energy);save();let url=URL.createObjectURL(new Blob([JSON.stringify(game,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='hero-clash-mobile-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}};
document.addEventListener('click',e=>{if(e.target.matches('select[data-equip]'))clearEquipmentNotice(e.target);let el=e.target.closest('[data-action]');if(el&&!el.disabled)actions[el.dataset.action]?.(el);});
document.addEventListener('keydown',e=>{if(e.target.matches('select[data-equip]')&&['Enter',' ','ArrowDown','ArrowUp'].includes(e.key))clearEquipmentNotice(e.target);});
document.addEventListener('change',async e=>{let el=e.target;if(el.dataset.appearance!==undefined){let h=page==='recruit'?candidate:page==='detail'?selected():null;if(!h||![0,1,2].includes(h.class))return;if(page==='recruit')h.name=$('#hero-name').value.slice(0,28);const key=el.dataset.appearance;if(setAppearance(h,key,+el.value)){if(page==='detail')save();render({preserveScroll:true});document.querySelector(`[data-appearance="${key}"]`)?.focus({preventScroll:true});}return;}if(el.id==='language'){game.lang=el.value;save();render();}if(el.dataset.equip!==undefined){clearEquipmentNotice(el);let h=selected();h.equipped[+el.dataset.equip]=+el.value;save();render({preserveScroll:true,focusSlot:+el.dataset.equip});}if(el.id==='arena-hero'){game.selected=el.value;opponents=[];save();render();}if(el.id==='import'&&el.files[0]){try{let data=JSON.parse(await el.files[0].text());if(!validSave(data))throw Error();if(!confirm(q('Remplacer la partie Web actuelle par cette sauvegarde ?','Replace the current web game with this backup?')))return;game=migrate(data);save();go('home');toast(q('Sauvegarde restaurée','Save restored'));}catch{toast(q('Fichier de sauvegarde Web invalide','Invalid web save file'));}}});
function validSave(d){if(d?.version!==2||!['en','fr'].includes(d.lang)||!Array.isArray(d.heroes)||d.heroes.length>5||!Array.isArray(d.graveyard))return false;return [...d.heroes,...d.graveyard].every(h=>h&&typeof h.id==='string'&&typeof h.name==='string'&&(h.appearance===undefined||validAppearance(h.appearance))&&(h.unseenSlots===undefined||Array.isArray(h.unseenSlots)&&h.unseenSlots.every(s=>Number.isInteger(s)&&s>=0&&s<4))&&(!h.arena||typeof h.arena.rerollUsed==='boolean'&&Array.isArray(h.arena.opponents)&&h.arena.opponents.length===3&&h.arena.opponents.every(o=>o&&!o.arena)&&validSave({version:2,lang:d.lang,heroes:h.arena.opponents,graveyard:[]}))&&Number.isInteger(h.class)&&h.class>=0&&h.class<13&&Number.isInteger(h.level)&&h.level>=1&&h.level<=20&&Number.isInteger(h.hearts)&&h.hearts>=0&&h.hearts<=5&&Array.isArray(h.stats)&&h.stats.length===5&&h.stats.every(Number.isFinite)&&Array.isArray(h.inventory)&&h.inventory.every(it=>Number.isInteger(it.id)&&it.id>=0&&it.id<19&&(it.rarity===undefined||Number.isInteger(it.rarity)&&it.rarity>=0&&it.rarity<=2)&&Number.isInteger(it.level)&&it.level>=1&&it.level<=20)&&Array.isArray(h.equipped)&&h.equipped.length===4&&h.equipped.every((v,s)=>Number.isInteger(v)&&(v===-1||(h.inventory[v]&&D.ITEMS[h.inventory[v].id].slot===s)))&&Array.isArray(h.pending)&&h.pending.every(p=>p.type==='stat'||p.type==='item'&&Array.isArray(p.offers)&&p.offers.length===3&&p.offers.every(it=>Number.isInteger(it.id)&&it.id>=0&&it.id<19&&Number.isFinite(it.level)))&&['xp','energy','energy_time','wins','losses','draws','damage_dealt','damage_taken','criticals','skills_used','combat_seconds','streak','best_streak'].every(k=>Number.isFinite(h[k])));}
